mapper.update:
update family_addresses
set contact_name = #{contactName}, contact_phone = #{contactPhone}, address_text = #{addressText}, is_default = #{defaultAddress}
where family_id = #{familyId} and id = #{id}

update families
set name = #{familyName}, note = #{note}, contact_names_json = #{contactNamesJson}
where merchant_id = #{merchantId} and id = #{familyId}

update families
set delivery_enabled = #{deliveryEnabled},
    delivery_fee_default = #{deliveryFeeDefault},
    delivery_fee_free = #{deliveryFree}
where merchant_id = #{merchantId} and id = #{familyId}
